import { useRef } from 'react';
import { Button, Code, Group, Stack, Surface, Title } from '@mantine/core';
import { formRootRule, hasLength, isNotEmpty, useForm, type FormErrors } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { FieldList } from './FieldList';
import { ModelDetails } from './ModelDetails';
import type { ContentModelValues } from './types';
import { KEY_ERROR, KEY_PATTERN, toModelJson } from './utils';

export function ContentModelForm() {
  const addFieldRef = useRef<HTMLButtonElement>(null);

  const form = useForm<ContentModelValues>({
    name: 'content-model',
    initialValues: {
      name: '',
      key: '',
      description: '',
      fields: [],
    },
    validateInputOnBlur: ['name', 'key', 'description'],
    validate: {
      name: (value) =>
        value.trim() === ''
          ? 'Model name is required'
          : hasLength({ min: 2, max: 60 }, 'Model name must be 2–60 characters')(value),
      key: (value) => {
        if (value === '') {
          return 'Model key is required';
        }
        return KEY_PATTERN.test(value) ? null : KEY_ERROR;
      },
      description: hasLength({ max: 200 }, 'Description must be 200 characters or fewer'),
      fields: {
        [formRootRule]: isNotEmpty('Add at least one field'),
      },
    },
  });

  const handleSubmit = (values: ContentModelValues) => {
    notifications.show({
      title: 'Content model created',
      message: <Code block>{JSON.stringify(toModelJson(values), null, 2)}</Code>,
      autoClose: false,
    });
  };

  const handleErrors = (errors: FormErrors) => {
    const firstPath = Object.keys(errors)[0];

    if (firstPath === 'fields') {
      addFieldRef.current?.focus();
    } else {
      form.getInputNode(firstPath)?.focus();
    }
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit, handleErrors)} noValidate>
      <Surface withBorder p="lg">
        <Stack gap="xl">
          <Title order={2} c="var(--mantine-color-bright)">
            New content model
          </Title>

          <ModelDetails form={form} />
          <FieldList form={form} addFieldRef={addFieldRef} />

          <Group justify="flex-end">
            {/* preventDefault keeps focus in the input so its blur error does not shift the button */}
            <Button type="submit" onMouseDown={(event) => event.preventDefault()}>
              Create model
            </Button>
          </Group>
        </Stack>
      </Surface>
    </form>
  );
}

import { render, screen, userEvent, waitFor, within } from '@test-utils';
import { notifications, Notifications } from '@mantine/notifications';
import { ContentModelForm } from './ContentModelForm';

type User = ReturnType<typeof userEvent.setup>;

// Autosize Textarea listens to font loading, jsdom has no FontFaceSet
Object.defineProperty(document, 'fonts', {
  configurable: true,
  value: { addEventListener: () => {}, removeEventListener: () => {} },
});

function setup() {
  const user = userEvent.setup();
  render(
    <>
      <Notifications />
      <ContentModelForm />
    </>
  );
  return user;
}

function getDialog() {
  return screen.getByRole('dialog');
}

async function waitForDialogToClose() {
  await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument());
}

function getFieldRows() {
  return within(screen.getByRole('list', { name: 'Fields' })).getAllByRole('listitem');
}

async function pickType(user: User, type: string) {
  await user.click(screen.getByRole('button', { name: 'Add field' }));
  await user.click(within(getDialog()).getByRole('button', { name: new RegExp(`^${type} `) }));
}

async function addField(
  user: User,
  type: string,
  label: string,
  configure?: (dialog: HTMLElement) => Promise<void>
) {
  await pickType(user, type);
  const dialog = getDialog();
  await user.type(within(dialog).getByRole('textbox', { name: 'Label' }), label);
  await configure?.(dialog);
  await user.click(within(dialog).getByRole('button', { name: 'Save' }));
  await waitForDialogToClose();
}

async function fillModel(user: User) {
  await user.type(screen.getByRole('textbox', { name: 'Model name' }), 'Blog post');
}

async function submitAndReadJson(user: User) {
  await user.click(screen.getByRole('button', { name: 'Create model' }));
  const title = await screen.findByText('Content model created');
  const notification = title.closest<HTMLElement>('[role="alert"]')!;
  return JSON.parse(within(notification).getByText(/"name"/).textContent!);
}

// jsdom has no layout: give every sortable row a position by its index so that
// dnd-kit keyboard sensor can find the row below
function mockRowRects() {
  const spy = vi
    .spyOn(Element.prototype, 'getBoundingClientRect')
    .mockImplementation(function getBoundingClientRect(this: Element) {
      const item = this.closest('[role="listitem"]');
      const index = item ? Array.from(item.parentElement!.children).indexOf(item) : 0;
      const top = index * 60;
      return {
        x: 0,
        y: top,
        top,
        left: 0,
        width: 400,
        height: 50,
        right: 400,
        bottom: top + 50,
        toJSON: () => ({}),
      };
    });
  return () => {
    spy.mockRestore();
  };
}

